"""Two-way sync between journeys and the team's flow files, with one source of truth (pack.yaml sync:).

source: journeys (default): each journey is the truth. `sync` writes it as a flow in sync.dir with a
"generated by Journeys" header and a hash of the flow, so a hand edit shows. A developer's own new
flow there (no header) is imported as a draft journey.

source: framework: the team's flows are the truth. `sync` imports each flow as a journey and imports
it again when the flow changes; a journey edited in Journeys instead is reported, never overwritten.

sync-state.json in the pack remembers which flow became which journey, with both hashes.
`check_sync` lists every drift; nothing changes silently.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
from dataclasses import dataclass
from pathlib import Path

import yaml

from .actions import ActionError
from .formats.maestro import export, import_flow, slug
from .journey import Journey
from .pack import Pack, PackError

MARK = "# generated by Journeys"
STATE = "sync-state.json"
CONFIG = ("config.yaml", "config.yml")  # Maestro's workspace config: never a flow, never written
_FROM = re.compile(r"^# generated by Journeys from journey (\S+);")
_HASH = re.compile(r"^# journeys-hash: ([0-9a-f]{16})$")


@dataclass
class Drift:
    kind: str           # missing, stale, hand-edited, orphan, unimported, name-taken, flow-changed, ...
    file: str           # the flow file (relative to sync.dir) or the journey file
    journey: str | None
    detail: str


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode()).hexdigest()[:16]


def journey_hash(j: Journey) -> str:
    """What a journey does (not where it sits or its comments): a hand edit in Journeys changes it."""
    return _sha(json.dumps([j.launch, j.clear_state, [(s.kind, s.arg) for s in j.steps]], sort_keys=True,
                           default=str))


def flow_dir(pack: Pack) -> Path:
    if not pack.sync:
        raise PackError("pack.yaml has no sync: section (sync: {dir: <the team's flow folder>})")
    d = (pack.root / pack.sync["dir"]).resolve()
    if d.exists() and not d.is_dir():
        raise PackError(f"sync.dir {d} is a file, not a folder")
    return d


def source(pack: Pack) -> str:
    return pack.sync.get("source", "journeys")


def render(pack: Pack, j: Journey) -> str:
    """The generated flow for a journey: the header, then the exported flow."""
    flow, notes = export(pack, j)
    body = flow.split("\n", 1)[1]  # the export's own first comment line names no file to edit
    head = [f"{MARK} from journey {j.name}; edit the journey in the pack, then run `journeys sync`.",
            f"# journeys-hash: {_sha(body)}", *(f"# note: {n}" for n in notes)]
    return "\n".join(head) + "\n" + body


def generated(text: str) -> tuple[str, str, str] | None:
    """(journey, recorded hash, body) for a file Journeys wrote, else None (a developer's own flow)."""
    lines = text.split("\n")
    m = _FROM.match(lines[0]) if lines else None
    h = _HASH.match(lines[1]) if len(lines) > 1 else None
    if not (m and h):
        return None
    i = 2
    while i < len(lines) and lines[i].startswith("# note: "):
        i += 1
    return m.group(1), h.group(1), "\n".join(lines[i:])


def _flows(pack: Pack) -> dict[str, str | None]:
    """Path in sync.dir (subfolders too) -> text of each flow (None: it cannot be read)."""
    d = flow_dir(pack)
    if not d.is_dir():
        return {}
    out = {}
    for f in sorted(d.rglob("*")):
        rel = f.relative_to(d).as_posix()
        if f.suffix not in (".yaml", ".yml") or not f.is_file() or any(p.startswith(".") for p in rel.split("/")):
            continue
        if rel in CONFIG:
            continue  # Maestro's workspace config, not a flow
        try:
            out[rel] = f.read_text()
        except (OSError, UnicodeDecodeError):
            out[rel] = None
    return out


def _state(pack: Pack) -> dict:
    try:
        data = json.loads((pack.root / STATE).read_text())
    except (FileNotFoundError, ValueError):
        return {}
    flows = data.get("flows") if isinstance(data, dict) else None
    if not isinstance(flows, dict):
        return {}
    return {k: v for k, v in flows.items() if isinstance(v, dict) and isinstance(v.get("journey"), str)
            and isinstance(v.get("hash"), str) and "journey_hash" in v
            and isinstance(v["journey_hash"], (str, type(None))) and isinstance(v.get("empty", False), bool)
            and isinstance(v.get("left_out", []), list) and all(isinstance(n, str) for n in v.get("left_out", []))
            and isinstance(v.get("declined", False), bool)}


def _state_broken(pack: Pack) -> bool:
    """sync-state.json is there but cannot be read: never save over it (its links would be lost)."""
    f = pack.root / STATE
    try:
        data = json.loads(f.read_text())
    except FileNotFoundError:
        return False
    except (OSError, ValueError):
        return True
    return not (isinstance(data, dict) and isinstance(data.get("flows", {}), dict))


def _save_state(pack: Pack, flows: dict) -> None:
    _write(pack.root / STATE, json.dumps({"flows": flows}, indent=1, sort_keys=True) + "\n")


def _write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.tmp")
    try:
        tmp.write_text(text)
        os.replace(tmp, path)
    finally:
        tmp.unlink(missing_ok=True)


def _relink(state: dict, every: dict) -> bool:
    """A journey renamed since its flow was imported: follow it by what it does. True if any moved."""
    moved = False
    for rec in state.values():
        if rec["journey"] not in every and rec["journey_hash"]:
            same = [n for n, j in every.items() if journey_hash(j) == rec["journey_hash"]]
            if len(same) == 1:
                rec["journey"], moved = same[0], True
    return moved


def check_sync(pack: Pack, state: dict | None = None) -> list[Drift]:
    """Every way the journeys and the flow files disagree. Empty means in sync."""
    flows, state = _flows(pack), _state(pack) if state is None else state
    every = {**pack.journeys, **pack.drafts}
    _relink(state, every)
    out = [Drift("unreadable", f, None, "cannot be read as text: fix or remove it") for f, t in flows.items() if t is None]
    if _state_broken(pack):
        out.append(Drift("bad-state", STATE, None, "cannot be read: fix it from git or delete it (its flow links "
                                                   "are then lost); sync will not write over it"))
    bad = {f for f, t in flows.items() if t is not None and not _parses(t)}
    out += [Drift("bad-flow", f, None, "not valid YAML: fix it, then sync") for f in sorted(bad)]
    broken = {f.lower() for f, t in flows.items() if t is None or f in bad}  # there, but never written over
    flows = {f: t for f, t in flows.items() if t is not None and f not in bad}
    folded = {f.lower(): f for f in flows}  # macOS and Windows folders ignore case: Open-Display.yaml is the same file
    if source(pack) == "journeys":
        for name, j in pack.journeys.items():  # drafts are not generated until promoted
            f = f"{name}.yaml"
            if f in CONFIG:
                out.append(Drift("name-taken", f, name, "Maestro's workspace config file: rename the journey"))
                continue
            if f.lower() in broken:
                continue  # reported above; a half-edited or broken file is never written over
            twin = next((o for o in flows if o.lower() == f"{name}.yml" and not generated(flows[o])), None)
            if twin and f not in flows:  # foo.yml beside journey foo: writing foo.yaml would give two flows
                out.append(Drift("name-taken", twin, name, f"a developer's flow with journey {name}'s name: rename "
                                 "one of them"))
                continue
            try:
                want = render(pack, j)
            except ActionError as e:
                out.append(Drift("unexportable", f, name, f"cannot be written as a flow: {e}"))
                continue
            if folded.get(f.lower(), f) != f:
                other = folded[f.lower()]
                rec = state.get(other)
                if rec and rec["journey"] == name and rec["hash"] == _sha(flows[other]):  # the flow it came from
                    out.append(_lossy(other, name, rec) or Drift("replace", other, name, f"the flow this journey "
                               f"came from: sync replaces it with the generated {f}"))
                else:
                    out.append(Drift("name-taken", other, name, f"differs from {f} only in case, and this folder "
                                     "may ignore case: rename one of them"))
                continue
            text = flows.get(f)
            if text is None:
                out.append(Drift("missing", f, name, "no flow file yet: run `journeys sync`"))
                continue
            gen = generated(text)
            if gen is None:
                rec = state.get(f)
                if rec and rec.get("hash") == _sha(text) and rec.get("journey") == name:
                    out.append(_lossy(f, name, rec) or Drift("stale", f, name, "the flow this journey came from: "
                                                                    "sync replaces it with the generated one"))
                else:
                    out.append(Drift("name-taken", f, name, "a developer's flow has this journey's file name: "
                                                            "rename one of them"))
            elif _sha(gen[2]) != gen[1]:
                out.append(Drift("hand-edited", f, name, "edited by hand: move the change into the journey, "
                                                         "then delete the file and run `journeys sync`"))
            elif want != text:
                out.append(Drift("stale", f, name, "the journey or the map changed: run `journeys sync`"))
        for f, text in flows.items():
            gen = generated(text)
            if gen and gen[0] not in pack.journeys:
                out.append(Drift("orphan", f, gen[0], "its journey is gone: `journeys sync --prune` deletes it"))
            elif gen and f != f"{gen[0]}.yaml":
                out.append(Drift("duplicate", f, gen[0], f"a generated flow of {gen[0]} under another name: "
                                                         "`journeys sync --prune` deletes it"))
            elif gen is None and not (f.lower().endswith(".yaml") and f.lower()[:-5] in pack.journeys):  # above
                rec, stem = state.get(f), Path(f).stem
                if rec and rec["journey"] not in every and rec["hash"] == _sha(text):
                    if not rec.get("declined"):  # deleted, or renamed and edited: a person says which
                        out.append(Drift("unlinked", f, rec["journey"], f"its draft {rec['journey']} is gone: "
                                         f"`journeys sync --decline {f}` keeps this flow out; if a journey you "
                                         "renamed replaces it, delete this file"))
                    continue
                if rec and rec["journey"] in every:
                    if rec["hash"] != _sha(text):
                        out.append(Drift("flow-edited", f, rec["journey"], f"changed after it became journey "
                                         f"{rec['journey']}: the journeys are the truth; move the change into "
                                         "the journey, then delete this file" if rec["journey"] in pack.journeys else
                                         f"changed after it became draft {rec['journey']}: edit the draft, or "
                                         "delete the draft and sync to import the flow again"))
                    elif rec["journey"] in pack.journeys and f.lower() != f"{rec['journey']}.yaml":
                        out.append(_lossy(f, rec["journey"], rec) or Drift(
                            "superseded", f, rec["journey"], f"the flow journey {rec['journey']} came from, now "
                            f"generated as {rec['journey']}.yaml: sync deletes this copy"))
                elif stem in pack.journeys:
                    out.append(Drift("name-taken", f, stem, "a developer's flow named like a journey: rename one"))
                else:
                    why = _unimportable(flow_dir(pack) / f, pack)
                    out.append(Drift("bad-flow", f, None, why) if why else
                               Drift("unimported", f, None, "a developer's flow: `journeys sync` imports it as a draft"))
    else:
        for f, text in flows.items():
            if generated(text):
                continue  # written by Journeys in the other mode: not a team flow
            rec = state.get(f)
            j = every.get(rec.get("journey")) if rec else None
            if not rec:
                out.append(Drift("new-flow", f, None, "`journeys sync` imports it as a draft"))
            elif j is None:
                out.append(Drift("journey-missing", f, rec.get("journey"), "its journey was deleted (or renamed "
                                 "and edited): `journeys sync` imports the flow again"))
            elif rec["journey_hash"] and journey_hash(j) != rec["journey_hash"]:
                both = rec["hash"] != _sha(text)
                out.append(Drift("conflict" if both else "journey-edited", str(j.file.relative_to(pack.root)), j.name,
                                 ("the flow changed too: " if both else "") +
                                 "edited in Journeys, but the flow is the truth: undo the edit (move it into "
                                 "the flow), then run `journeys sync`"))
            elif rec["hash"] != _sha(text):
                out.append(Drift("flow-changed", f, j.name, "`journeys sync` imports the change"))
        for f, rec in state.items():
            if f not in flows and f.lower() not in broken and rec["journey"] in every:  # both gone: sync drops the record
                out.append(Drift("flow-removed", f, rec.get("journey"), "its flow is gone: delete the journey "
                                                                        "or put the flow back"))
        made = {rec.get("journey") for rec in state.values()}
        for name, j in pack.journeys.items():
            if name not in made:
                out.append(Drift("journey-only", str(j.file.relative_to(pack.root)), name,
                                 "no flow: the flows are the truth here; write it as a flow"))
    for f, rec in state.items():  # a flow nothing could be taken from: its draft tests nothing
        j = every.get(rec["journey"])
        if rec.get("empty") and j and journey_hash(j) == rec["journey_hash"] and f in flows:
            out.append(Drift("empty-import", f, j.name, "no command of the flow could be imported: write the "
                                                        "journey's steps by hand, or delete it"))
    return out


def _unimportable(path: Path, pack: Pack) -> str | None:
    """Why a flow cannot be imported (an empty or header-only file), else None."""
    try:
        import_flow(path, pack.app)
    except (ActionError, yaml.YAMLError, OSError, UnicodeDecodeError) as e:
        return f"cannot be imported: {e}"
    return None


def _parses(text: str) -> bool:
    try:
        list(yaml.safe_load_all(text))
        return True
    except yaml.YAMLError:
        return False


def _lossy(f: str, journey: str, rec: dict) -> Drift | None:
    """A developer's flow whose import left something out: replacing or deleting it would lose that."""
    if not rec.get("left_out"):
        return None
    return Drift("lossy", f, journey, f"its import left out {len(rec['left_out'])} thing(s) "
                 f"({'; '.join(rec['left_out'])[:300]}): carry them into the journey, then run "
                 f"`journeys sync --accept {f}` to let the generated flow replace it")


def _import(pack: Pack, f: str, text: str, state: dict, notes: list[str], dest: Path | None = None,
            name: str | None = None, write: bool = True) -> str | None:
    """Import one flow as a draft (or over `dest`), record it in the state; the journey's name or None."""
    path = flow_dir(pack) / f
    try:
        draft, more = import_flow(path, pack.app)
    except (ActionError, yaml.YAMLError, OSError, UnicodeDecodeError) as e:
        notes.append(f"{f}: not imported: {e}")
        return None
    draft["name"] = name or draft["name"]
    if dest is None:
        taken = lambda n: n in pack.journeys or n in pack.drafts or (pack.root / "drafts" / f"{n}.yaml").exists()
        if "/" in f and taken(draft["name"]):  # auth/login.yaml next to checkout/login.yaml: auth-login
            draft["name"] = slug(f.rsplit(".", 1)[0].replace("/", "-"))
        if draft["name"] == "all" or draft["name"] in pack.sets:
            draft["name"] += "-flow"
        dest = pack.root / "drafts" / f"{draft['name']}.yaml"
        if draft["name"] in pack.journeys or draft["name"] in pack.drafts or dest.exists():
            notes.append(f"{f}: not imported: a journey or draft named {draft['name']} exists; rename the flow "
                         "or that journey")
            return None
    else:  # the flow owns the steps; tags and other keys added in Journeys stay
        try:
            old = yaml.safe_load(dest.read_text())
        except (OSError, yaml.YAMLError):
            old = None
        listed = isinstance(old, list) and len(old) == 1 and isinstance(old[0], dict)  # `- name: x` form
        old = old[0] if listed else old
        if isinstance(old, dict):
            draft = {**{k: v for k, v in old.items() if k not in ("steps", "start")},
                     "steps": draft["steps"], "start": draft["start"], "name": draft["name"]}
        if listed:
            draft = [draft]
    if not write:  # a dry run: every check above, nothing written
        return draft[0]["name"] if isinstance(draft, list) else draft["name"]
    comment = f"# synced from {pack.sync['dir']}/{f}: the flow is the truth; edit it, then run `journeys sync`\n" \
        if source(pack) == "framework" else f"# imported from {pack.sync['dir']}/{f}\n"
    _write(dest, comment + yaml.safe_dump(draft, sort_keys=False, allow_unicode=True))
    notes += [f"{f}: {n}" for n in more]
    draft = draft[0] if isinstance(draft, list) else draft
    loaded = Pack.load(pack.root)
    j = loaded.journeys.get(draft["name"]) or loaded.drafts.get(draft["name"])
    state[f] = {"journey": draft["name"], "hash": _sha(text), "journey_hash": journey_hash(j) if j else None,
                "empty": any("no command could be imported" in n for n in more),
                "left_out": [n for n in more if "left out" in n or "no command could be imported" in n]}
    return draft["name"]


def sync(pack: Pack, dry_run: bool = False, prune: bool = False,
         accept: list[str] | None = None, decline: list[str] | None = None) -> tuple[list[str], list[Drift]]:
    """Fix what can be fixed safely; return what was done and the drift that is left for a person.
    accept: developer flows whose left-out parts a person has dealt with (see `lossy`).
    decline: developer flows whose draft was deleted on purpose (see `unlinked`): kept out from now on."""
    if _state_broken(pack):
        return [], [d for d in check_sync(pack) if d.kind == "bad-state"]  # writing now would lose its links
    state = _state(pack)
    every = {**pack.journeys, **pack.drafts}
    decline = [a.removeprefix("./") for a in decline or []]
    bad_decline = [Drift("not-declined", a, None, "not an unlinked flow: use its path as check-sync prints it")
                   for a in decline if not (a in state and state[a]["journey"] not in every)]
    for a in decline:
        if a in state and state[a]["journey"] not in every:
            state[a]["declined"] = True
    accept = [a.removeprefix("./") for a in accept or []]
    bad_accept = [Drift("not-accepted", a, None, "not a lossy flow: use its path in sync.dir as check-sync "
                        "prints it") for a in accept if not (a in state and state[a].get("left_out"))]
    for a in accept:
        if a in state:
            state[a]["left_out"] = []
    moved = _relink(state, {**pack.journeys, **pack.drafts})
    if (moved or len(bad_accept) < len(accept) or len(bad_decline) < len(decline)) and not dry_run:
        _save_state(pack, state)
    drift, flows = check_sync(pack, state), _flows(pack)
    planned = {f"{x.journey}.yaml" for x in drift if x.kind in ("missing", "stale", "replace")}
    done: list[str] = []
    left: list[Drift] = bad_accept + bad_decline
    later: list[Drift] = []
    d = flow_dir(pack)
    for x in drift:
        if x.kind == "replace":  # a developer's flow named like the journey but for case: same file here
            done.append(f"replace {x.file} with the generated {x.journey}.yaml")
            if not dry_run:
                (d / x.file).unlink()
                _write(d / f"{x.journey}.yaml", render(pack, pack.journeys[x.journey]))
                state.pop(x.file, None)
        elif x.kind in ("missing", "stale") and source(pack) == "journeys":
            done.append(f"write {x.file} from journey {x.journey}")
            if not dry_run:
                _write(d / x.file, render(pack, pack.journeys[x.journey]))
                state.pop(x.file, None)  # generated now: no longer a developer's flow
        elif x.kind in ("orphan", "duplicate") and prune:
            gen = generated(flows[x.file])
            if _sha(gen[2]) != gen[1]:  # edited by hand since: a person's work, never pruned
                left.append(Drift("hand-edited", x.file, x.journey, "edited by hand: not pruned"))
                continue
            done.append(f"delete {x.file} ({'journey ' + x.journey + ' is gone' if x.kind == 'orphan' else 'a duplicate'})")
            if not dry_run:
                (d / x.file).unlink()
        elif x.kind in ("unimported", "new-flow", "journey-missing"):
            done.append(f"import {x.file} as a draft")
            notes: list[str] = []
            if _import(pack, x.file, flows[x.file], state, notes, write=not dry_run) is None:
                left.append(Drift("not-imported", x.file, None, "; ".join(notes)))
                done.pop()
            else:
                done += [f"  note {n}" for n in notes]
        elif x.kind == "flow-changed":
            j = {**pack.journeys, **pack.drafts}[x.journey]
            if sum(o.file == j.file for o in {**pack.journeys, **pack.drafts}.values()) > 1:
                left.append(Drift("shared-file", str(j.file.relative_to(pack.root)), j.name,
                                  "the journey shares its file with others: give it its own file, then sync"))
                continue
            done.append(f"update journey {j.name} from {x.file}")
            notes = []
            if _import(pack, x.file, flows[x.file], state, notes, dest=j.file, name=j.name, write=not dry_run) is None:
                done.pop()
                left.append(Drift("not-imported", x.file, j.name, "; ".join(notes)))
        elif x.kind == "superseded":
            later.append(x)
        else:
            left.append(x)
    for x in later:  # a developer's copy goes only once its journey's generated flow is there
        target = d / f"{x.journey}.yaml"
        try:
            ready = target.exists() and generated(target.read_text())
        except (OSError, UnicodeDecodeError):
            ready = False
        if ready or (dry_run and target.name in planned):
            done.append(f"delete {x.file} (now generated as {x.journey}.yaml)")
            if not dry_run:
                (d / x.file).unlink()
                state.pop(x.file, None)
                parent = (d / x.file).parent
                if parent != d and not any(parent.iterdir()):
                    parent.rmdir()  # the folder it was in, now empty
        else:
            left.append(x)
    gone = [k for k, rec in state.items() if k not in flows and
            (source(pack) == "journeys" or rec["journey"] not in every)]
    for k in gone:  # a developer's file someone deleted: nothing left to remember
        state.pop(k)
    if not dry_run and (done or gone):
        _save_state(pack, state)
    return done, left
